package com.jnapanam.sportszone.training.model;
import com.jnapanam.sportszone.catalog.model.Facility;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Entity @Table(name="training_batches")public class TrainingBatch{
 @Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="program_id")private TrainingProgram program;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="facility_id")private Facility facility;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="coach_user_id")private User coach;@Column(nullable=false,length=140)private String name;@Column(name="start_date",nullable=false)private LocalDate startDate;@Column(name="end_date",nullable=false)private LocalDate endDate;@Column(name="start_time",nullable=false)private LocalTime startTime;@Column(name="end_time",nullable=false)private LocalTime endTime;@Column(name="days_of_week",nullable=false,length=80)private String daysOfWeek;@Column(nullable=false)private int capacity;@Column(nullable=false,precision=12,scale=2)private BigDecimal fee;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private TrainingStatus status;@Version private long version;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;
 protected TrainingBatch(){}public TrainingBatch(TrainingProgram p,Facility f,User c,String n,LocalDate sd,LocalDate ed,LocalTime st,LocalTime et,Set<DayOfWeek>d,int cap,BigDecimal fee){id=UUID.randomUUID();program=p;update(f,c,n,sd,ed,st,et,d,cap,fee);status=TrainingStatus.ACTIVE;createdAt=Instant.now();updatedAt=createdAt;}public void update(Facility f,User c,String n,LocalDate sd,LocalDate ed,LocalTime st,LocalTime et,Set<DayOfWeek>d,int cap,BigDecimal fee){facility=f;coach=c;name=n.trim();startDate=sd;endDate=ed;startTime=st;endTime=et;daysOfWeek=d.stream().sorted().map(Enum::name).collect(java.util.stream.Collectors.joining(","));capacity=cap;this.fee=fee;updatedAt=Instant.now();}public void status(TrainingStatus s){status=s;updatedAt=Instant.now();}
 public UUID getId(){return id;}public TrainingProgram getProgram(){return program;}public Facility getFacility(){return facility;}public User getCoach(){return coach;}public String getName(){return name;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public LocalTime getStartTime(){return startTime;}public LocalTime getEndTime(){return endTime;}public Set<DayOfWeek> getDaysOfWeek(){Set<DayOfWeek>s=new LinkedHashSet<>();for(String v:daysOfWeek.split(","))s.add(DayOfWeek.valueOf(v));return s;}public int getCapacity(){return capacity;}public BigDecimal getFee(){return fee;}public TrainingStatus getStatus(){return status;}
}
